#!/usr/bin/env node
// tools/build-search-aliases.mjs — writes data/search-aliases.json, the collector-nickname list the two search boxes read
// (home #h2-q in js/home-v2.js, the header box generated by tools/build-nav.js).
//
// Q-069 (Build Loop, Nov 27 2026; CoS handoff claude/handoffs/cos-2026-11-27-lookup-path-rows.md L-1, LEDGER O-129):
// "Moonbreon", the home box's own suggested search, returned nothing although Umbreon VMAX #215 is priced in
// data/card-search.json. A nickname maps to card ids and guide pages; it is a name, never a price. Every id must exist in
// data/card-search.json with a price and every page must exist, or the build fails (no alias may point at a dead end).
// Add a nickname only with its source (a Pokémon KB line, R40). Run: node tools/build-search-aliases.mjs [--check]
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT = path.join(ROOT, "data/search-aliases.json");
const CHECK = process.argv.includes("--check");

// Q-084 (Build Loop, Nov 28 2026; CoS handoff rows-2 M-3): the list now comes from the Pokémon KB nickname file, a verbatim
// copy of the Project doc claude/kb/pokemon/NICKNAMES.json kept at the same path in this repo. Each entry: ids (first = the
// default the box returns), optional alsoMatches (listed after the default), pages, sources. Entries under "held" are not read.
// --lenient (nightly feed): an id that is missing or unpriced in card-search.json is dropped with a warning instead of failing;
// an alias left with no card and no page is dropped. A missing page still fails.
const KB = path.join(ROOT, "claude/kb/pokemon/NICKNAMES.json");
const LENIENT = process.argv.includes("--lenient");
const kb = JSON.parse(fs.readFileSync(KB, "utf8"));
const ALIASES = Object.entries(kb.aliases || {}).map(([key, a]) => ({
  key,
  ids: [...(a.ids || []), ...(a.alsoMatches || [])],
  pages: a.pages || [],
  source: "Pokémon KB NICKNAMES.json (" + (kb.updated || "") + "): " + (a.sources || []).join(" | "),
}));
if (ALIASES.some((a) => !a.source || !(kb.aliases[a.key].sources || []).length)) { console.error("build-search-aliases: an alias has no source"); process.exit(1); }

const nk = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
const cards = new Map((JSON.parse(fs.readFileSync(path.join(ROOT, "data/card-search.json"), "utf8")).cards || []).map((c) => [c[0], c]));
const bad = [];
const out = {};
for (const a of ALIASES) {
  const k = nk(a.key);
  const ids = [];
  for (const id of a.ids) { const c = cards.get(id); const why = !c ? `${k}: ${id} not in card-search.json` : c[3] == null ? `${k}: ${id} has no price` : null; if (!why) ids.push(id); else if (LENIENT) console.warn("build-search-aliases: dropped " + why); else bad.push(why); }
  for (const p of a.pages) if (!fs.existsSync(path.join(ROOT, p.replace(/^\//, "") + ".html"))) bad.push(`${k}: ${p} has no page`);
  if (!ids.length && !a.pages.length) { console.warn(`build-search-aliases: dropped ${k} (no priced card, no page)`); continue; }
  out[k] = { ids, pages: a.pages, source: a.source };
}
if (bad.length) { console.error("build-search-aliases: " + bad.join("; ")); process.exit(1); }
const json = JSON.stringify({ _comment: "Generated by tools/build-search-aliases.mjs (Q-069, Q-084) from claude/kb/pokemon/NICKNAMES.json. Collector nicknames → card ids (data/card-search.json) and guide pages, read by the home and header search boxes. Names only, never a price. Do not hand-edit: change the tool and re-run.", aliases: out }, null, 1) + "\n";
const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
if (CHECK) { console.log(cur === json ? "search-aliases: up to date" : "search-aliases: STALE"); process.exit(cur === json ? 0 : 1); }
if (cur !== json) fs.writeFileSync(OUT, json);
console.log(`search-aliases: ${Object.keys(out).length} nickname(s) → ${path.relative(ROOT, OUT)}`);
